import requests

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema import Data


class SearchProducts(Component):

    display_name = "SearchProducts"
    name = "SearchProducts"

    inputs = [
        MessageTextInput(
            name="text",
            display_name="Search Text",
            tool_mode=True,
        ),
    ]

    outputs = [
        Output(
            name="output",
            display_name="Output",
            method="execute_tool",
        ),
    ]

    def execute_tool(self) -> Data:

        response = requests.get(
            "http://127.0.0.1:8000/search_products/",
            params={
                "text": self.text
            }
        )

        return Data(
            data=response.json(),
            text=str(response.json())
        )

import requests

from langflow.custom import Component
from langflow.io import MessageTextInput, IntInput, Output
from langflow.schema import Data


class AddProductToCart(Component):

    display_name = "AddProductToCart"
    name = "AddProductToCart"

    inputs = [
        MessageTextInput(
            name="product_name",
            display_name="Product Name",
            tool_mode=True,
        ),
        IntInput(
            name="quantity",
            display_name="Quantity",
            value=1,
            tool_mode=True,
        ),
    ]

    outputs = [
        Output(
            name="output",
            display_name="Output",
            method="execute_tool",
        )
    ]

    def execute_tool(self) -> Data:
        try:
            response = requests.post(
                "http://127.0.0.1:8000/add_product_to_cart/",
                params={
                    "product_name": self.product_name,
                    "quantity": self.quantity
                },
                timeout=10
            )

            response.raise_for_status()

            result = response.json()

            return Data(
                data=result,
                text=str(result)
            )

        except Exception as e:
            return Data(
                data={"error": str(e)},
                text=str(e)
            )

